def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            t, v = peek()
            if t == '+' or t == '-':
                advance()
                rhs = parse_term()
                if t == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            t, v = peek()
            if t == '*' or t == '/':
                advance()
                rhs = parse_factor()
                if t == '*':
                    val = val * rhs
                else:
                    val = int_div(val, rhs)
            else:
                break
        return val

    def parse_factor():
        t, v = peek()
        if t == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        t, v = peek()
        if t == 'NUM':
            advance()
            return v
        if t == '(':
            advance()
            val = parse_expr()
            t2, v2 = peek()
            if t2 != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {t}")

    def int_div(a, b):
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

